#!/usr/bin/env python3

import copy
import io
import os
import tempfile
import unittest
from contextlib import redirect_stdout
from pathlib import Path
from unittest import mock

import megahal
from megahal import Brain, MegaHAL, main

SENTENCES = [
    "Python is a programming language that lets you work quickly.",
    "I love Python because it makes programming fun.",
    "Markov chains are used to generate random text.",
    "The weather today is sunny and warm.",
    "Do you like sunny weather or rainy weather?",
    "Random text generated by Markov chains can be funny.",
    "Chatbots talk to people using generated text.",
]


class TokenizerTest(unittest.TestCase):
    def tokens(self, phrase):
        return Brain.get_words_from_phrase(phrase)

    def test_words_and_separators_are_kept(self):
        self.assertEqual(self.tokens("Hello, world"), ["HELLO", ", ", "WORLD", "."])

    def test_apostrophes_inside_words(self):
        self.assertEqual(self.tokens("I don't know!"), ["I", " ", "DON'T", " ", "KNOW", "!"])

    def test_digits_are_separate_words(self):
        self.assertEqual(self.tokens("abc123"), ["ABC", "123", "."])

    def test_trailing_punctuation_is_normalized(self):
        self.assertEqual(self.tokens("fine..."), ["FINE", "..."])
        self.assertEqual(self.tokens("what?"), ["WHAT", "?"])
        self.assertEqual(self.tokens("hm, "), ["HM", "."])

    def test_edge_cases_do_not_crash(self):
        self.assertEqual(self.tokens(""), [])
        self.assertEqual(self.tokens("a"), ["A", "."])
        self.assertEqual(self.tokens("hello'"), ["HELLO", "."])
        self.assertEqual(self.tokens("'"), ["."])
        self.assertEqual(self.tokens("   "), ["."])

    def test_unicode(self):
        self.assertEqual(self.tokens("příliš žluťoučký kůň"), ["PŘÍLIŠ", " ", "ŽLUŤOUČKÝ", " ", "KŮŇ", "."])


class MegaHALTest(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.brainfile = os.path.join(self.tmp.name, "brain")

    def tearDown(self):
        self.tmp.cleanup()

    def bot(self, **kwargs):
        kwargs.setdefault("brainfile", self.brainfile)
        kwargs.setdefault("timeout", 0.05)
        return MegaHAL(**kwargs)

    def test_empty_brain_has_nothing_to_say(self):
        with self.bot() as bot:
            self.assertEqual(bot.get_reply_nolearn("Hello"), "I don't know enough to answer you yet!")

    def test_replies_are_built_from_learned_words(self):
        with self.bot() as bot:
            for sentence in SENTENCES:
                bot.learn(sentence)
            known = {word for sentence in SENTENCES for word in Brain.get_words_from_phrase(sentence)}
            for _ in range(10):
                reply = bot.get_reply("Tell me about Python and Markov chains")
                self.assertTrue(reply)
                self.assertTrue(reply[0].isupper())
                self.assertTrue(set(Brain.get_words_from_phrase(reply)) <= known, reply)

    def test_reply_prefers_keywords(self):
        with self.bot(timeout=0.5) as bot:
            for sentence in SENTENCES:
                bot.learn(sentence)
            replies = [bot.get_reply_nolearn("weather").upper() for _ in range(5)]
            self.assertTrue(any("WEATHER" in reply for reply in replies), replies)

    def test_short_phrases_are_not_learned(self):
        with self.bot(order=5) as bot:
            bot.learn("Hi there")
            self.assertEqual(bot.get_reply_nolearn("Hi"), "I don't know enough to answer you yet!")

    def test_learn_persists_across_reopen(self):
        with self.bot() as bot:
            bot.learn("A brand new sentence with a zebra inside")
        with self.bot() as bot:
            self.assertIn("ZEBRA", bot._MegaHAL__brain.dictionary)
            self.assertEqual(bot.get_reply_nolearn("zebra").upper(), "A BRAND NEW SENTENCE WITH A ZEBRA INSIDE.")

    def test_replying_does_not_modify_the_brain(self):
        with self.bot() as bot:
            for sentence in SENTENCES:
                bot.learn(sentence)
            brain = bot._MegaHAL__brain
            before = copy.deepcopy((brain.forward, brain.backward, list(brain.dictionary)))
            bot.get_reply_nolearn("Python is fun, do you like sunny weather?")
            after = (brain.forward, brain.backward, list(brain.dictionary))
            self.assertEqual(self.dump(before), self.dump(after))

    def test_get_reply_learns(self):
        with self.bot() as bot:
            bot.get_reply("My favourite animal is the capybara")
            self.assertIn("CAPYBARA", bot._MegaHAL__brain.dictionary)

    def test_order_mismatch_is_rejected(self):
        with self.bot(order=3):
            pass
        with self.assertRaises(ValueError):
            self.bot(order=4)

    def test_train_from_file(self):
        path = Path(self.tmp.name) / "corpus.txt"
        path.write_text("# a comment\n\n" + "\n".join(SENTENCES) + "\n", encoding="utf-8")
        with self.bot() as bot:
            bot.train(path)
            self.assertIn("PYTHON", bot._MegaHAL__brain.dictionary)
            self.assertNotIn("COMMENT", bot._MegaHAL__brain.dictionary)

    def test_word_lists_are_stored_in_brain(self):
        with self.bot() as bot:
            bot.banwords.append("ZEBRA")
            bot.swapwords["CAT"] = "DOG"
        with self.bot() as bot:
            self.assertIn("ZEBRA", bot.banwords)
            self.assertEqual(bot.swapwords["CAT"], "DOG")
        self.assertNotIn("CAT", megahal.DEFAULT_SWAPWORDS)

    def test_pathlike_brainfile(self):
        with MegaHAL(brainfile=Path(self.brainfile), timeout=0) as bot:
            bot.learn(SENTENCES[0])

    def test_sync_and_close(self):
        bot = self.bot()
        bot.learn(SENTENCES[0])
        bot.sync()
        bot.close()
        bot.close()  # closing twice is fine

    def test_cli(self):
        corpus = Path(self.tmp.name) / "corpus.txt"
        corpus.write_text("\n".join(SENTENCES), encoding="utf-8")
        answers = iter(["what is python?", "", "weather"])

        def fake_input(prompt):
            try:
                return next(answers)
            except StopIteration:
                raise EOFError from None

        with mock.patch("builtins.input", fake_input), redirect_stdout(io.StringIO()) as out:
            code = main(["-b", self.brainfile, "-t", "0.05", "-T", str(corpus)])
        self.assertEqual(code, 0)
        self.assertEqual(len(out.getvalue().strip().splitlines()), 2)
        with self.bot() as bot:
            self.assertIn("PYTHON", bot._MegaHAL__brain.dictionary)

    def test_cli_version(self):
        with redirect_stdout(io.StringIO()) as out, self.assertRaises(SystemExit):
            main(["--version"])
        self.assertEqual(out.getvalue().strip(), f"megahal {megahal.__version__}")

    @staticmethod
    def dump(state):
        forward, backward, dictionary = state

        def tree(node):
            return (node.symbol, node.usage, node.count, [tree(child) for child in node.children])

        return tree(forward), tree(backward), dictionary


if __name__ == "__main__":
    unittest.main()
